// The example pages' data, generated by scripts/build-examples.ts from the conformance corpus
// (packages/cellb/conformance): one entry per scenario.
import data from "../generated/examples.json";

export interface Example {
  name: string;
  project: string;
  /** Whose project it is: one of celld's examples, cellb's own probes, or workerd's tests. */
  origin: "celld" | "cellb" | "workerd";
  about: string;
  /** The project on GitHub (celld's repository for celld's examples). */
  source: string;
  /** workerd's test file, for workerd's tests. */
  upstream?: string;
  files: { path: string; text: string }[];
  steps: string[];
  seconds: number;
  logs: boolean;
  needsServer: boolean;
  judge: "celld" | "workerd";
  knownGap?: string;
  workerdDiffers?: string;
  recorded: { transcript: unknown[]; logs?: string[]; celld?: string };
}

export const examples = data as Example[];
export const exampleByName = new Map(examples.map((e) => [e.name, e]));
export const exampleHref = (name: string) => `/examples/${name}`;

export const ORIGIN_LABEL: Record<Example["origin"], string> = {
  celld: "celld's example",
  cellb: "CellB's probe project",
  workerd: "workerd's test",
};

/** How to run a project in an app, as these pages run it in the browser. */
export function integration(e: Example) {
  const first = e.steps.find((s) => /^[A-Z]+ \//.test(s));
  const path = first ? first.split(" ")[1].replace(/\{[^}]+\}/g, "") : "/";
  const req = `new Request("http://localhost${path}")`;
  const dir = e.project;
  return {
    node: `import { loadProject } from "@statewalker/cellb/node";

// The folder celld deploys: wrangler.jsonc and the Worker's sources
const project = await loadProject("./${dir}", { data: "./data" });

const res = await project.fetch(${req});
console.log(res.status, await res.text());
await project.close();`,
    build: `# Once, on your machine or in CI: the folder a browser loads
npx cellb build ./${dir} --out public/built/${dir}`,
    browser: `// In a Dedicated Worker
import { loadProject } from "@statewalker/cellb/browser";

// The folder cellb build wrote, served by any static host (this page loads /built/${dir}/)
const project = await loadProject("/built/${dir}/", { data: "${dir}" });

const res = await project.fetch(${req});
console.log(res.status, await res.text());
await project.close();`,
  };
}
